def count_neighbors(grid, i, j):
    count = 0
    for x in range(max(0, i-1), min(len(grid), i+2)):
        for y in range(max(0, j-1), min(len(grid[0]), j+2)):
            if (x, y) != (i, j) and grid[x][y] == grid[i][j]:
                count += 1
    return count

def transform_grid(grid):
    output = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                output[i][j] = 1
            elif grid[i][j] == 6:
                output[i][j] = 6 if count_neighbors(grid, i, j) >= 3 else 0
            elif grid[i][j] == 8:
                output[i][j] = 8 if count_neighbors(grid, i, j) >= 2 else 0
            elif grid[i][j] == 0:
                count_1 = count_neighbors(grid, i, j)
                output[i][j] = 6 if count_1 >= 3 else 0
    return output

